//! C-alignment regression tests (step 5g). GENERATED by target/perf-work/step5g/gen_tests.py: every expected
//! value is what C SQLite 3.54.1 produces for the same statements (file bytes are compared through a 64-bit
//! FNV-1a hash of the whole database file C wrote). Nothing here depends on files outside the repository.
use crate::Connection;
use sqliters_types::Value;

fn fnv1a(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3)
    })
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-5g-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn side(&self, suffix: &str) -> std::path::PathBuf {
        let mut s = self.0.clone().into_os_string();
        s.push(suffix);
        s.into()
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let _ = std::fs::remove_file(self.side(suffix));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

fn render(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Text(s) => s.clone(),
        Value::Blob(b) => String::from_utf8_lossy(b).into_owned(),
        Value::Real(r) if r.fract() == 0.0 && r.abs() < 1e15 => format!("{r:.1}"),
        Value::Real(r) => format!("{r}"),
    }
}

fn rows(conn: &Connection, sql: &str) -> Vec<String> {
    conn.query(sql, &[])
        .unwrap_or_else(|e| panic!("{sql}: {e:?}"))
        .rows
        .iter()
        .map(|r| r.values().iter().map(render).collect::<Vec<_>>().join("|"))
        .collect()
}

/// Runs `stmts` on a new database file and returns the file.
fn file_after(name: &str, stmts: &[&str]) -> Vec<u8> {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        conn.query(sql, &[])
            .unwrap_or_else(|e| panic!("{sql}: {e:?}"));
    }
    assert!(conn.try_close().is_ok());
    std::fs::read(&db.0).unwrap()
}

fn assert_file_is_what_c_writes(name: &str, stmts: &[&str], c_size: usize, c_hash: u64) {
    let bytes = file_after(name, stmts);
    assert_eq!(bytes.len(), c_size, "{name}: file size");
    assert_eq!(
        fnv1a(&bytes),
        c_hash,
        "{name}: file bytes differ from the file C writes"
    );
}

/// H1 change counter in every journal mode, H3 VACUUM cookie: the database file is byte-identical to the one C writes.
#[test]
fn file_g_h1_modes() {
    assert_file_is_what_c_writes(
        "g_h1_modes",
        &[
            "PRAGMA journal_mode=PERSIST;",
            "CREATE TABLE t(a,b);",
            "INSERT INTO t VALUES(1,'x');",
            "PRAGMA journal_mode=TRUNCATE;",
            "INSERT INTO t VALUES(2,'x');",
            "PRAGMA journal_mode=MEMORY;",
            "INSERT INTO t VALUES(3,'x');",
            "PRAGMA journal_mode=OFF;",
            "INSERT INTO t VALUES(4,'x');",
            "PRAGMA user_version=7;",
            "PRAGMA application_id=9;",
            "PRAGMA journal_mode=DELETE;",
            "PRAGMA auto_vacuum=1;",
            "VACUUM;",
            "INSERT INTO t VALUES(5,'x');",
        ],
        12288,
        0x6647d70264054ed7,
    );
}

