/// V3 JSONB element types of edit functions: the database file is byte-identical to the one C writes.
#[test]
fn file_g_v3_jsonb() {
    assert_file_is_what_c_writes(
        "g_v3_jsonb",
        &[
            "CREATE TABLE j(id INTEGER PRIMARY KEY, d BLOB);",
            "INSERT INTO j VALUES(1, jsonb('{\"a\":1}'));",
            "INSERT INTO j VALUES(2, jsonb_set(jsonb('{\"a\":1}'),'$.new',5));",
            "INSERT INTO j VALUES(3, jsonb_replace(jsonb('{\"a\":1}'),'$.a','yy'));",
            "INSERT INTO j VALUES(4, jsonb_insert(jsonb('[1]'),'$[#]','z'));",
            "INSERT INTO j VALUES(5, jsonb_set('{}','$.\"a b\"','q'));",
            "INSERT INTO j VALUES(6, jsonb_set('{}','$.a.b.c','q'));",
            "INSERT INTO j VALUES(7, jsonb_array('x','a b',1));",
            "INSERT INTO j VALUES(8, jsonb_object('k','v'));",
            "INSERT INTO j VALUES(9, jsonb_set('[]','$[0]',json('\"jj\"')));",
            "INSERT INTO j VALUES(10, jsonb_array_insert('[1,2]','$[1]','mid'));",
            "INSERT INTO j VALUES(11, jsonb_set('{\"a\":{\"b\":1}}','$.a.c','x','$.a.b','y','$.z[0]', 'w'));",
            "INSERT INTO j VALUES(12, jsonb_insert('{\"a\":1}','$.a','no','$.b', 'yes', '$.c', 1.5, '$.d', NULL, '$.e', x'00'));",
            "UPDATE j SET d = jsonb_set(d, '$.upd', 'text value') WHERE id IN (1,2,5);",
            "UPDATE j SET d = jsonb_replace(d, '$.a', 'r') WHERE id = 1;",
            "SELECT id, hex(d), json(d) FROM j ORDER BY id;",
        ],
        8192,
        0x5d2185de897a1fae,
    );
}

